post_theorem_intro_text:
\noindent
	The proof of Theorem 1.1 shows that the argument can be generalized to the case where $2<s<t$. Let $I=\{2,...,t\}$ and denote by $I_{s-1}$ the set of all subsets $\{i_2,...,i_{s}\}\subset I$ consisting of $s-1$ distinct elements of $I$. Assume that for any $j=2,...,s$ there exists an $i_j$ such that $n_j>a_{i_j}$. Then the diophantine equations simplifies to
	\begin{eqnarray}
	\prod_{i\notin\{1,i_2,...,i_{s}\}}a_i!= \prod_{j=1}^s\Delta(m_j,k_j),
	\end{eqnarray}
	where $m_j=a_{i_j}+1$ and $k_j=n_j-a_{i_j}$ for $j=2,...,s$. Notice that $m_1=a_1+1$ and $k_1=n_1-a_1$. Let $\mathrm{max}\{k_2,...,k_s\}=k$ and let $c>0$ be an arbitrary but fixed positive integer.  We define the following set
	$$
	\mathcal{N}(c)_{\{i_2,...,i_{s}\}}=\{\textnormal{nontrivial solutions to (2)}\mid n_1>a_1, n_j>a_{i_j} \quad \textnormal{and} \quad k/k_1\leq c \}.
	$$
	Then we define 
	$$
	\mathcal{N}(c)=\bigcup_{\{i_2,...,i_{s}\}\in I_{s-1}}\mathcal{N}(c)_{\{i_2,...,i_{s}\}}.
	$$
	\begin{thm}
		The explicit abc conjecture implies that (2) has only finitely many solutions $(a_1,...,a_t,n_1,...,n_s)\in \mathcal{N}(c)_{\{i_2,...,i_{s}\}}$.  Hence the explicit abc conjecture implies that
		$$
		\prod_{i=1}^ta_i!=\prod_{j=1}^sn_i!
		$$
		has finitely many solutions $(a_1,...,a_t,n_1,...,n_s)\in \mathcal{N}(c)$.
	\end{thm}
	\begin{rema2}
	\textnormal{One could make Theorems 1.1 and 1.2 explicit by keeping track of all the constants and coefficients in the estimates that appear in the proofs. But that is not our intention.}
	\end{rema2}
	\noindent
	Let $d(\mathcal{N}(c))$ denote the asymptotic density of $\mathcal{N}(c)$ in $\mathbb{N}^{t+s}$. We consider equation (1). Since $\mathcal{N}(c)_i\not\subset \mathcal{N}(c)_j$ for $i\neq j$, we get $d(\mathcal{N}(c))\geq d(\mathcal{N}(c)_i)$. The next result shows that $\mathcal{N}(c)$ is large in the sense that its asymptotic density is positive. 
	\begin{thm}
		We have $d(\mathcal{N}(c)_i)>0$.
	\end{thm}
	\noindent
	Diophantine equations of the form $a_1!\cdots a_t!=f(x,y)$ have also been studied quite frequently in the literature and we neither want to give a complete list of reference here nor we want to recall the main results with respect to such equations. We refer, for instance, to \cite{EO}, \cite{WT}, \cite{NA1}, \cite{NO} or \cite{NOO} and references therein. We just want to mention that showing that such an equation has finitely many integer solutions is still a widely open problem. In particular, if $f(x,y)$ is an arbitrary reducible and non-homogeneous polynomial. Theorem 1.2 from above essentially treats one special case. Fix a positive integer $k_i>0$ and let $P(x_i)=x_i(x_i+1)\cdots (x_i+k_i-1)$ be an integer polynomial. Now consider the equation
	\begin{eqnarray}
\prod_{i=1}^ta_i!=\prod_{j=1}^sP(x_i)
	\end{eqnarray}
	Again, let $\mathrm{max}\{k_2,...,k_s\}=k$ and $c>0$ be an arbitrary but fixed positive integer. Define
	$$
	\mathcal{L}=\{\textnormal{integer solutions to (3)} \mid x_1\geq \cdots \geq x_s, x_1>a_1\geq \cdots \geq a_t, k/k_1\leq c\}
	$$
	\begin{thm}
		The explicit abc conjecture implies that equation (3) has only finitely many integer solutions $(a_1,...,a_t,x_1,...,x_s)\in \mathcal{L}$.  
	\end{thm}
	\noindent
	The proof is in fact the same as for Theorem 1.2 since the statement of Theorem 1.4 is just a reformulation in terms of polynomials.

mcq.question:
Let $H$ be a split classical group over a field $F$, and let $\phi\in\Phi_{\mathrm{temp}}(H(F))$. Assume one of the following holds:
(B) $H=\SO_{2n+1}$, $p>6n+3$, and $\phi$ is arbitrary;
(C) $H=\Sp_{2n}$, $p>6n$, and $\phi$ satisfies $(\star)$;
(D) $H=\SO_{2n}$, $p>6n$, and $\phi$ satisfies $(\star)$.
Set $\psi=\widehat\phi$. Which statement (under these assumptions, and with the additional conditional hypothesis stated within it) gives the exact existence/maximality and upper-bound conclusions for elements $\pi\in\Pi_\psi$ and their associated stable nilpotent orbits?

ref_dict.thm:smooth:
\begin{theorem}\label{thm:smooth}
For any $d \ge 1$ and $\beta > 0$, there exist a convex $\beta$-smooth set $S_\beta$ and a $1$-smooth, $1$-strongly convex function $f_\beta$ such that every \texttt{LMO-span} method applied to $(f_\beta, S_\beta)$ starting from $x_0=0$ has for all $t\leq d-1$
    \begin{equation}
        f_\beta(x_t) - \min_{x\in S_\beta}f_\beta(x) \geq  \max \left(0, \sqrt{\frac{d-t}{2}}\left(\frac{\mathrm{diam}(S_\beta) -  2/\beta}{\sqrt{2}d}+\frac{1}{\beta\sqrt{d}}\right)-\frac{1}{\sqrt{2}\beta}\right)^2  . 
    \end{equation}
    In particular, for any fixed budget $T \ge 1$, there exist $S_\beta$ and $f_\beta$ in dimension $d=2T$ such that
    \[
        f_\beta(x_T) - \min_{x\in S_\beta}f_\beta(x) \geq \max\left(0,\frac{\mathrm{diam}(S_\beta) - 2/\beta}{4\sqrt{T}} - \frac{\sqrt{2}-1}{2\beta }\right)^2 .
    \]
\end{theorem}

ref_dict.thm:mixed:
\begin{theorem}\label{thm:mixed}
    For any $d \ge 1$ and $\beta > 0$, there exist a $\beta$-smooth, $1/(1+1/\beta)$-strongly convex set $S_\beta$ and a $1$-smooth, $1$-strongly convex function $f_\beta$ such that every \texttt{LMO-span} method applied to $(f_\beta, S_\beta)$ starting from $x_0 = 0$ has for all $t\leq d-1$
    \begin{equation}
        f_\beta(x_t) - \min_{x\in S_\beta}f_\beta(x) \geq \max\left(0,\sqrt{\frac{2}{5}\frac{(d-t)(\mathrm{diam}(S_\beta) -  2/\beta)^2}{(d+2)^3}} - \frac{1}{\sqrt{2}\beta}\right)^2  . 
    \end{equation}
    In particular, for any fixed budget $T \ge 1$, there exist $S_\beta$ and $f_\beta$ in dimension $d=2(T+1)$ such that
    \[
        f_\beta(x_T) - \min_{x\in S_\beta}f_\beta(x) \geq \max\left(0,\frac{\mathrm{diam}(S_\beta) - 2/\beta}{\sqrt{20}(T+2)} - \frac{1}{\sqrt{2}\beta }\right)^2  .
    \]
\end{theorem}

theorem.content:
\label{thm}
Assume $1\leq p <2$, $d\geq 1$ and the pressure $P$ satisfies $P'(\bar{\rho})>0$ for $\bar{\rho}>0$. There is a small constant $\delta_1>0$ such that if
$
\|(n_0,\bv_0)\|_{\dB_{p,1}^{\frac{d}{p}}}^{\ell,J_\varepsilon}
+\varepsilon\|(n_0,\bv_0)\|_{\dB_{2,1}^{\frac{d}{2}+1}}^{h,J_\varepsilon}
\leq \delta_1,
$
then the Cauchy problem \eqref{1.2}-\eqref{1.2initial} admits a uniform global unique solution in $E_\infty^{J_\varepsilon}$ for all $\varepsilon>0$.

ref_dict.NonClassicalProLaw1:
\begin{lemma}\label{NonClassicalProLaw1}
Let $0<s_1<\frac{d}{2}$, $1\leq p<2$. Then, we have the following inequality
\begin{align}\label{newproduct}
\|ab\|_{\dB_{p,1}^{s_1}}^{\ell,J_\varepsilon}
\leq C
\left(\|b\|_{\dB_{p,1}^{s_1}}^{\ell,J_\varepsilon}+ 2^{(s_1-\frac{d}{p})J_\varepsilon}\|b\|_{\dB_{2,1}^{\frac{d}{2}}}^{h,J_\varepsilon} \right)\|a\|_{\dB_{2,1}^{\frac{d}{2}}}
\end{align}
with $C$ independent on $\varepsilon$.
\end{lemma}

