ref_dict.cor:1.2:
\begin{corollary}\label{cor:1.2}
Let $p$ be a prime or $0$. Then there exists a quartic del Pezzo surface over a global field of characteristic $p$ not admitting a quadratic point if and only if $p\neq 2$.
\end{corollary}

ref_dict.thm:maindp4:
\begin{theorem}\label{thm:maindp4}
Let $p>2$ be a prime. There exist  infinitely many non-isomorphic quartic del Pezzo surfaces $X$ over $\F_p(t)$ such that $X(K)=\varnothing$ for all quadratic extensions $K/\F_p(t)$. 
\end{theorem}

ref_dict.mainConjecture:
\begin{conjecture}\label{mainConjecture}
    Given positive integers with $i<j\leq k <\ell$ and $i+\ell = j+k$, there is an inclusion of $\FIS$-modules:
    \[A^i\otimes A^\ell \hookrightarrow A^j\otimes A^k,\]
    and
    \[C^{i}\otimes C^{\ell}\hookrightarrow C^{j}\otimes C^{k}.\]
\end{conjecture}

ref_dict.maintheorem:
\begin{theorem}\label{maintheorem}
    Given positive integers $i<j\leq k<\ell$ with $i+\ell =j+k=m$, for $m\leq 19$ we have an inclusion of $\FIS$-modules
    \[A^i\otimes A^\ell \hookrightarrow A^j\otimes A^k,\]
    and
    \[C^{i}\otimes C^{\ell}\hookrightarrow C^{j}\otimes C^{k}.\]
\end{theorem}

ref_dict.stableBound:
\begin{remark}\label{stableBound}
    This bound is lower than the stabilization degree for these $\FB$-modules, which are $3(j+k)+2$ for $A^j\otimes A^k$ and $3(j+k)$ for $C^j\otimes C^k$ by Corollary \ref{AiandCiStabilizationDegree}.
\end{remark}

post_theorem_intro_text:
\begin{corollary}\label{maincorollary}
    For all $n$, the graded representations $A_n^\bullet$ and $C_n^{\bullet}$ are strongly equivariantly log concave up to degree 19.
\end{corollary}

While \cite{MMPR23}*{Theorem 1.7} proves that these inclusions are $\frakS_n$-equivariant, we show that they also respect the rigid $\operatorname{FI^\sharp}$-module structures on $A^i$ and $C^i$. As we will see in Remark \ref{stableBound}, the stronger $\operatorname{FI^\sharp}$-module structure can be completely determined with fewer computations.  Hence, we are able to prove Conjecture \ref{mainConjecture} up to degree 19 and obtain strong equivariant log concavity of the graded representations as a corollary.

First, we review the necessary results of representation theory that make these calculations possible. Then, by using the equivalence of the categories $\operatorname{FB-mod}$ and $\operatorname{FI^\sharp-mod}$, we observe that the determining the $\operatorname{FI^\sharp}$-module structures of $A^i\otimes A^j$ and $C^i\otimes C^j$ requires fewer computations than explicitly calculating them as $\operatorname{FB}$-modules.  Finally, we describe the algorithm that calculates the $\operatorname{FI^\sharp}$-module structures of $A^i\otimes A^j$ and $C^i\otimes C^j$ and proves Theorem \ref{maintheorem}. We run this algorithm using the software package SageMath \cite{Sage}.

\vspace{\baselineskip}
\noindent
{\em Acknowledgments:}
We are grateful to Nicholas Proudfoot for his mentorship, guidance, and comments throughout the preparation of this manuscript. We would also like to thank Eric Ramos for the insights into determining the structure of a tensor product of $\operatorname{FI^\sharp}$-modules. Finally, we thank Galen Dorpalen-Barry and the Texas A\&M compute cluster Whistler for providing the computing power necessary to prove Theorem \ref{maintheorem}.

ref_dict.thm:capillaryConeExistence:
\begin{theorem}\label{thm:capillaryConeExistence}
    For all $n \geq 4$, $2 \leq k \leq n-2$, and $\theta \in (0,\tfrac{\pi}{2}]$, there exists a capillary minimal cone $\tilde{\mathbf{C}}_{n,k,\theta}$ that is topologically $C(\bS^{n-k-1}\times \bS^{k-1}\times [0,1])$ with isometry group $O(n-k) \times O(k)$. 

    The double of the free-boundary cone $\tilde{\mathbf{C}}_{n,k,\frac{\pi}{2}}$ is a non-isoparametric minimal hypercone $\hat{\mathbf{C}}_{n,k} \subset \bR^{n+1}$.
    Its link $\mathbf{S}_{n,k} \subset \bS^n$ is topologically $\bS^{n-k-1} \times \bS^{k-1} \times \bS^1$, invariant under $O(n-k) \times O(k) \times \bZ_2$.
\end{theorem}

