theorem.content:
\label{thm:Intro}
Let $H$ be a non-zero constant and $h=h(s)\colon I \to \mathbb{R}$ be a smooth function on an interval $I\subset \mathbb{R}$ with non-vanishing derivative. Then there exist 
\begin{itemize}
\item a null curve $\gamma=\gamma(s)$ with a null frame $(A,B,C)$ satisfying $d\gamma/ds = A$, 
\begin{equation}\label{eq:ABC_Intro}
A=\frac{S(h)}{H^2}B+\frac{1}{H^2}B'',\quad B= -\frac{H}{2h'} 
{ \left(-1-h^2, 1-h^2, 2h\right)},\quad C=\frac{1}{H}B'
\end{equation}
and the Frenet-Serret equations
\begin{equation}\label{eq:FS_Intro}
(A',B', C')=(A,B,C)\begin{pmatrix}
0 & 0 & H  \\
0 & 0  &  -S(h)/H \\
-S(h)/H  & H  & 0
\end{pmatrix},
\end{equation}
where $S(h)$ is the Schwarzian derivative of $h$,
\item a harmonic map $N_L=-C-tHB$ into $\mathbb{S}^2_1$ satisfying $\Box N_L=2H^2N_L$ with respect to the d'Alambert operator $\Box$ for the Lorentzian metric $\mathrm{I}=t^2H^2ds^2-2dsdt$,
\item a regular timelike B-scroll $f_L(s,t)=\gamma(s)+tB(s)$ in $\mathbb{L}^3$ with constant mean curvature $H$ whose first fundamental form is $\mathrm{I}$ and the Gauss map is $N_L$, and
\item a timelike minimal surface $f=f(s,t)$ in $\operatorname{Nil}_3(H)$ which corresponds to $f_L$ via the duality in Fact \ref{fact:correspond}.
\end{itemize}

Moreover, regarding on singularities of $f$ in $\operatorname{Nil}_3(H)$, the following assertions hold.
\begin{itemize}
\item[(1)] The surface $f$ always has singular points and the singular set is $\Sigma=\{(s,t)\in I\times \mathbb{R}\mid t=-\frac{C_3(s)}{HB_3(s)}\}$, where $B=(B_1,B_2,B_3)$ and $C=(C_1,C_2,C_3)$. 
\end{itemize}
\begin{itemize}
\item[(2)] The surface $f$ is a front at $(s,t)\in \Sigma$ if and only if $S(h)(s)\neq 0$.
\item[(3)] The surface $f$ is $\mathcal{A}$-equivalent to the cuspidal cross cap at $(s,t)\in \Sigma$ if and only if $S(h)(s)= 0$ and $S(h)'(s)\neq 0$.
\end{itemize}

ref_dict.cor:invariance1:
\begin{corollary}[Invariance of singularities]\label{cor:invariance1}
Let $(s,t)$ be a singular point of a B-scroll type timelike minimal surface $f$ in $\Nil(H)$ and $(s,t^O)$ be the corresponding singular point of $f^O$ as above. Then the following statements hold.
\begin{itemize}
\item[(1)] $f$ is a front at $(s,t)$ if and only if $f^O$ is a front at $(s,t^O)$.
\item[(2)] $f$ is $\mathcal{A}$-equivalent to the cuspidal cross cap at $(s,t)$ if and only if $f^O$is $\mathcal{A}$-equivalent to the cuspidal cross cap at at $(s,t^O)$.
\end{itemize}
In particular, if $f$ has a cuspidal cross cap, then the family $\{f^O\}_{O\in O(2,1)}$ consists of B-scroll type timelike minimal surfaces in $\Nil(H)$ with a cuspidal cross cap.
\end{corollary}

ref_dict.cor:Intro:
\begin{corollary}\label{cor:Intro}
For a function $h$ satisfying the condition (3) in Theorem \ref{thm:Intro}, there exists a family of timelike minimal surfaces $\{f^{O}\}_{O\in O(2,1)}$ in $\Nil(H)$ associated with the Lorentz orthogonal group $O(2,1)$ such that each surface $f^{O}$ admits a cuspidal cross cap.
\end{corollary}

