\end{itemize}
\end{theorem}

expanded_sketch:
In Sections \ref{sec:3} and \ref{sec:4} the authors indicate how the main theorem is proved: Section \ref{sec:3} "describe[s] the construction of timelike ruled surfaces in $\mathbb{L}^3$ with constant mean curvature $H$, called {\it B-scrolls}, from framed null curves in $\mathbb{L}^3$, and the corresponding timelike minimal surfaces in $\operatorname{Nil}_3(H)$ via the following fact.

\begin{fact}[\cite{AK1}, cf.  {\cite[Theorem 4.1]{KK}}]\label{fact:correspond}
For arbitrary real constant $H\neq 0$, any solution $g$ to the equation \eqref{eq:Harmonic} and the 1-form $\omega=\hat{\omega} dz$ defined by $\hat\omega = -j \bar{g}_{z} / (1+|g|^2)^2$, the following assertions hold.
\begin{itemize}
\item[(1)] The following surface $f_L$ with Gauss map $N_L$
\[
f_L = \frac{2}{H}\Re \bigintss \begin{pmatrix} g^2+1\\j(g^2-1)\\2jg \end{pmatrix}\omega,\quad N_L = \frac{ -1}{1+|g|^2} \begin{pmatrix} j (g-\bar{g}) \\ g+\bar{g} \\ 1-|g|^2 \end{pmatrix}, 
\]
gives a timelike constant mean curvature $H$ surface in Lorentz-Minkowski $3$-space $\mathbb{L}^3$ with signature $(-++)$.
\item[(2)]  The following surface $f$ 
\[
f =\begin{pmatrix} f^1\\f^2\\f^3 \end{pmatrix}=  \frac{2}{H}\Re \bigintss \begin{pmatrix} g^2+1\\j(g^2-1)\\2g-H f^2(g^2+1)+H f^1j(g^2-1) \end{pmatrix}\omega
\]
gives a timelike minimal surface in Lorentzian Heisenberg group $\Nil(H)$ with a left invariant metric $g_+$ whose Gauss map is  
\[
N=\frac{g+\bar{g} }{1-|g|^2} E_1+ \frac{j(g-\bar{g}) }{1-|g|^2} E_2+ \frac{1+|g|^2}{1-|g|^2} E_3,
 \]
 where $\{E_1,E_2,E_3\}$ is an orthonormal basis consisting of left invariant vector fields of $\Nil(H)$ so that $g_+(E_1, E_1)=-1$ and $g_+(E_2, E_2)=g_+(E_3, E_3)=1$.\end{itemize}
\end{fact}

In particular, "the part of the proof of the main theorem concerning the harmonic map $N_L$ is given" there.

Then Section~\ref{sec:4} gives "the remaining part of the proof of the main theorem": first, the following theorem provides criteria for $f$ to be "a front" and to have "a cuspidal cross cap singularity" in terms of the curvature invariant $\kappa_2$ of framed null curves.

\begin{theorem}\label{thm:criteria_Bscroll}
Let $f_L$ and $f$ be a null scroll with constant mean curvature $H$ in $\mathbb{L}^3$ written as \eqref{eq:Bscroll} and its corresponding null scroll type surface in $\Nil(H)$.
For a point $(s,t)\in I \times \mathbb{R}$, the following assertions hold.
\begin{itemize}
\item[(1)] $(s,t)$ is a singular point of $f$ if and only if $t= -\frac{C_3(s)}{HB_3(s)}$. Furthermore, any such a singular point $(s,t)$ is non-degenerate.
\item[(2)] $f$ is a front at a singular point $(s,t)$ if and only if $\kappa_2(s)  \neq 0$,
\item[(3)] $f$ is $\mathcal{A}$-equivalent to the cuspidal cross cap at  a singular point $(s,t)$ if and only if 
\[
\kappa_2(s)=0\quad \text{and} \quad \kappa_2'(s)=0.
\]
\end{itemize}\end{theorem}

Next, Section~4.2 shows "that any framed null curve is generated from a certain one-variable function $h$" and the following theorem states that "$\kappa_2$ is written by the Schwarzian derivative of $h$" (linking the singularity criteria to the conditions $S(h)\neq 0$ and $S(h)=0,\ S(h)'\neq 0$ appearing in establishing the main theorem).

\begin{theorem}\label{thm:Schwarzian_criterion}
For any non-zero constant $H$ and any smooth function $h=h(s)\colon I \to \mathbb{R}$ with non-vanishing derivative, there exists a regular timelike constant mean curvature $H$ B-scroll $f_L(s,t)=\gamma(s)+tB(s)$ in $\mathbb{L}^3$ associated with the null frame $(A,B,C)$ satisfying \eqref{eq:frame_cond}, 
\begin{equation}\label{eq:ABC_h}
A=\frac{S(h)}{H^2}B+\frac{1}{H^2}B'',\quad B= -\frac{H}{2h'} 
{ \left(-1-h^2, 1-h^2, 2h\right)},\quad C=\frac{1}{H}B'
\end{equation}
and the Frenet-Serret equations
\begin{equation}\label{eq:FS_Bscroll_2}
(A',B', C')=(A,B,C)\begin{pmatrix}
0 & 0 & H  \\
0 & 0  &  -S(h)/H \\
-S(h)/H  & H  & 0
\end{pmatrix}.
\end{equation}

Moreover, for its corresponding timelike minimal surface $f$ in $\Nil(H)$, the following assertions hold.
\begin{itemize}
\item[(1)] $(s,t)\in I\times \mathbb{R}$ is a singular point of $f$ if and only if $t=-\frac{C_3(s)}{HB_3(s)}$, where $B=(B_1,B_2,B_3)$ and $C=(C_1,C_2,C_3)$. Furthermore, any singular point is non-degenerate.
\end{itemize}

Let $(s,t)$ be a singular point of $f$. Then,
\begin{itemize}
\item[(2)] $f$ is a front at $(s,t)$ if and only if $S(h)(s)\neq 0$.
\item[(3)] $f$ is $\mathcal{A}$-equivalent to the cuspidal cross cap at $(s,t)$ if and only if $S(h)(s)= 0$ and $S(h)'(s)\neq 0$.
\end{itemize}
\end{theorem}

