\section{Variation of the flat trace with explicit coefficients}\label{variationofflattrace}

This section records the explicit form of the $\delta'$-constraint in geometric terms.
For each fixed $t$ the flat trace of the Koopman operator of the geodesic flow is given by the (exact) Lefschetz/Guillemin formula
\begin{equation}\label{eq:flat_trace_exact}
\mathrm{Tr}^{\flat}V_{t}(\tau)
=
\sum_{\gamma\in\mathcal{P}(g_t)}\ \sum_{m\geq 1}
\frac{L_{\gamma}^{\#}(t)}{\left|\det\!\left(I-P_{\gamma,t}^{\,m}\right)\right|}\,
\delta\!\big(\tau-L_{\gamma^m}(t)\big)
\;+\;C^\infty(\tau),
\end{equation}

ref_dict.mostsingularterm:
\begin{proposition}\label{mostsingularterm}
    At each isolated length $\ell >0$, the length-transport coefficient of $\delta'(\tau - \ell)$, in $\partial_t\big|_0 \mathrm{Tr}^{\flat} V_{t}(\tau)$ equals
$$\mathcal{T}(\ell): = -  \sum_{\substack{\gamma, m \\ L_{\gamma^m} = \ell  }}  \frac{L^\#_\gamma}{|\det(I - P^m_\gamma)|} \dot{L}_{\gamma^m}.
$$
In particular, if $\mathrm{Tr}^{\flat} V_{t}$ is constant in $t$, then for every $\ell$, $\mathcal{T}(\ell) = 0$.
\end{proposition}

