\label{thm1}
Assume (F), \eqref{init1} and \eqref{init3} and let $u$ be a solution of \eqref{Rea-Diff}. Then there exists a smooth function  $\gamma=\gamma(x,t)$ with the following properties.
\begin{enumerate}
\item[(i)] 
There exists $T>0$ such that 
\begin{equation*}
\{ (x,y,t) \in \mathbf{R}^{n-1} \times \mathbf{R} \times [T,\infty); \, u(x,y,t)=\Phi_c(0)\}=\{y=\gamma(x,t)\}.
\end{equation*}
Moreover, it holds that
\begin{equation*}
\lim_{t\rightarrow\infty}\sup_{(x,y)\in\mathbf{R}^n }|u(x,y,t)-\Phi_c(y-\gamma(x,t))|=0.
\end{equation*}
\item[(ii)]
For any $\varepsilon>0$, there exists $\tau_{\varepsilon}\in[T,\infty)$ such that the solution $U(x,t)$ of the problem
\begin{equation}\label{MCF}
\left\{
\begin{aligned}
&\frac{U_t}{\sqrt{1+|\nabla_x U|^2}}=\mathrm{div}\left(\frac{\nabla_x U}{\sqrt{1+|\nabla_x U|}}\right)+c_*,&&x\in\mathbf{R}^{n-1},t>0,\\
&U(x,0)=\gamma(x,\tau_{\varepsilon}),&&x\in\mathbf{R}^{n-1},
\end{aligned}
\right.
\end{equation}
satisfies
\begin{equation*}
\sup_{x\in\mathbf{R}^{n-1},t\ge\tau_{\varepsilon}}|\gamma(x,t)-U(x,t-\tau_{\varepsilon})|\le\varepsilon.
\end{equation*}
\end{enumerate}
Furthermore, the assertion (i) still holds if \eqref{init2} is assumed instead of \eqref{init3}.

