\label{main th}

There exists a minimizing couple $(u,\ell)$ of the following problem in both variables
\begin{equation}
    \label{pb min}
    \min\left \{E_\varepsilon(u,\ell), \, u \in  H^{1}({\mathcal C}) \text{ such that } 0\leqslant u \leqslant 1 , \, u = 1 \text{ on } \partial{{\mathcal C}} \text{ and } \ell \in \mathrm{Hom}^\Lambda(\gamma_0,\gamma_1) \right\}.
\end{equation}

Moreover, the minimizer $u$ is $\alpha$-H\"older continuous for all $0<\alpha<1$ with the estimate:
\[\|u\|_{C^{0,\alpha}(\mathcal{C})} \leqslant C_\alpha \frac{1+\Lambda c_\varepsilon ^{-1}}{\varepsilon^{\alpha}}.\]

ref_dict.def:kqdefineskd:
\begin{definition}
 \label{def:kqdefineskd} Let $\oslash$ be a Kronecker quotient. The Kronecker difference $\ominus$ induced by $\oslash$ is the
 Kronecker difference given by
 \begin{equation*}
  M\ominus B := (M-I_m\otimes B)\oslash I_n
 \end{equation*}
 for all $M\in\mathbb{F}_{mn}$, $B\in\mathbb{F}_n$ and $m,n\in\mathbb{N}$.
\end{definition}

ref_dict.rem:kqdefineskd:
\begin{remark}
 \label{rem:kqdefineskd} It is easily verified that this expression satisfies the condition for a
 Kronecker difference, i.e. for every $A\in\mathbb{F}_m$, $B\in\mathbb{F}_n$ and $m,n\in\mathbb{N}$,
 \begin{align*}
  (A\oplus B)\ominus B
   &= (A\otimes I_n + I_m\otimes B)\ominus B \\
   &= (A\otimes I_n + I_m\otimes B - I_m\otimes B)\oslash I_n \\
   &= (A\otimes I_n)\oslash I_n \\
   &= A.
 \end{align*}
\end{remark}

post_theorem_intro_text:
\begin{proof}
 Let $B,C\in\mathbb{F}_m$ with $C\neq 0$. Then there exists
 an non-zero entry $(C)_{i,j}\neq 0$ in $C$. Now let $f:\mathbb{F}_m\to\mathbb{N}\times\mathbb{N}$
 be defined by $f(C)=(i,j)$ and $f(0_m)=(1,1)$, i.e. $f$ chooses a non-zero entry of $C$, unless
 $C$ is the zero matrix. Define $\text{---}\oslash C$
 as the linear extension of
 \begin{equation*}
  (A\otimes B)\oslash C := A\dfrac{(B)_{f(C)}}{(C)_{f(C)}}
 \end{equation*}
 for all $A\in\mathbb{F}_s$, $s\in\mathbb{N}$. Then
 $\oslash$ is a uniform Kronecker quotient by construction.
\end{proof}

\subsection{Kronecker sums and Kronecker differences}

The Kronecker sum $A\oplus B$ of an $m\times m$ matrix $A$ and an
$n\times n$ matrix $B$ is given by \cite[pp. 268]{horn91}
\begin{equation*}
 A\oplus B = A\otimes I_n + I_m\otimes B.
\end{equation*}
Over the real and complex numbers, we have
\begin{equation*}
 \exp(A\oplus B) = \exp(A)\otimes\exp(B).
\end{equation*}
The Kronecker sum uniquely satisfies the above equation. The Kronecker sum
also arises in the study of matrix equations of the form
\begin{equation*}
 BX+XA^T = Y
\end{equation*}
where $X$ is the subject of the equation. Taking the vectorization (vec)
on both sides of the equation, and using the fact that $\vc(ABC)=(C^T\otimes A)\vc(B)$,
yields \cite[pp. 268]{horn91}
\begin{equation*}
 (A\oplus B) \vc(X) = \vc(Y).
\end{equation*}

This article defines and studies Kronecker differences and their connection with Kronecker
quotients \cite{kronquotient}.
Similar to the definition of Kronecker quotients, we consider the family $\ominus:\mathbb{F}_{mn}\times\mathbb{F}_n\to\mathbb{F}_m$
indexed by $m,n\in\mathbb{N}$ satisfying the following definition:

\begin{definition}
 \label{def:kqdifference} A Kronecker difference is an operation $\ominus$ satisfying
 \begin{equation*}
  (A\oplus B)\ominus B = A
 \end{equation*}
 for all matrices $A\in\mathbb{F}_{m}$ and $B\in\mathbb{F}_{n}$,
 $m,n\in\mathbb{N}$.
\end{definition}

Every Kronecker quotient induces a Kronecker difference in the following way.

\begin{definition}
 \label{def:kqdefineskd} Let $\oslash$ be a Kronecker quotient. The Kronecker difference $\ominus$ induced by $\oslash$ is the
 Kronecker difference given by
 \begin{equation*}
  M\ominus B := (M-I_m\otimes B)\oslash I_n
 \end{equation*}
 for all $M\in\mathbb{F}_{mn}$, $B\in\mathbb{F}_n$ and $m,n\in\mathbb{N}$.
\end{definition}

\begin{remark}
 \label{rem:kqdefineskd} It is easily verified that this expression satisfies the condition for a
 Kronecker difference, i.e. for every $A\in\mathbb{F}_m$, $B\in\mathbb{F}_n$ and $m,n\in\mathbb{N}$,
 \begin{align*}
  (A\oplus B)\ominus B
   &= (A\otimes I_n + I_m\otimes B)\ominus B \\
   &= (A\otimes I_n + I_m\otimes B - I_m\otimes B)\oslash I_n \\
   &= (A\otimes I_n)\oslash I_n \\
   &= A.
 \end{align*}
\end{remark}

\begin{remark}[Duality 1]
 \label{rem:kddefineskq} Definition \ref{def:kqdefineskd} has a weak dual, namely: Let $\oslash$ be a Kronecker quotient such that
 \begin{equation*}
  M\oslash B = (M(0_m\oplus B)^{-1})\ominus 0_n
 \end{equation*}
 for all $M\in\mathbb{F}_{mn}$, invertible $B\in\mathbb{F}_n$ and $m,n\in\mathbb{N}$,
 where $\ominus$ is a Kronecker difference. Indeed, for invertible $B$,
 $(0_m\oplus B)^{-1} = (I_m\otimes B)^{-1} = I_m\otimes B^{-1}$ and
 \begin{align*}
  (A\otimes B)\oslash B
   &= ((A\otimes I_n)(I_m\otimes B))\oslash B \\
   &= ((A\otimes I_n)(I_m\otimes B)(I_m\otimes B)^{-1})\ominus 0_n \\
   &= (A\oplus 0_n)\ominus 0_n \\
   &= A.
 \end{align*}
\end{remark}

The notion of uniformity in Kronecker quotients has an analogue for Kronecker differences. 
\begin{definition}
 \label{def:kduniform} A Kronecker difference $\ominus$ is a uniform Kronecker difference if
 \begin{equation*}
  (A\oplus C)\ominus B = A\oplus (C\ominus B)
 \end{equation*}
 for all matrices $A\in\mathbb{F}_{m}$, $B\in\mathbb{F}_n$, $C\in\mathbb{F}_p\otimes\mathbb{F}_n$ and $m,n,p\in\mathbb{N}$,
 and
 \begin{equation*}
  (A+B)\ominus (C+D) = (A\ominus C)+(B\ominus D), \qquad
  (kA)\ominus (kC) = k(A\ominus C)
 \end{equation*}
 for all matrices $A$, $B$, $C$ and $D$, and scalars $k\in\mathbb{F}$ whenever the operations are defined.
\end{definition}
Once again, we immediately have a connection between uniform Kronecker quotients and uniform Kronecker differences.

\begin{proposition}
 \label{prop:ukqdefinesukd} Let $\oslash$ be a uniform Kronecker quotient.
 Then the induced Kronecker difference $\ominus$ is uniform.
\end{proposition}

\begin{proof}
 Following the definition in Definition \ref{def:kqdefineskd},  \begin{equation*}
  M\ominus B := (M-I_m\otimes B)\oslash I_n
 \end{equation*}
 for all $M\in\mathbb{F}_{mn}$, $B\in\mathbb{F}_n$ and $m,n\in\mathbb{N}$,
 where $\oslash$ is a uniform Kronecker quotient.
 In Remark \ref{rem:kqdefineskd} it was shown that $\ominus$ is a Kronecker difference,
 it remains to show that this Kronecker difference is uniform.
 We have for all $A\in\mathbb{F}_{m}$, $B\in\mathbb{F}_n$, and $C\in\mathbb{F}_p\otimes\mathbb{F}_n$, 
 \begin{align*}
  (A\oplus C)\ominus B
   &= (A\otimes I_p\otimes I_n + I_m\otimes C - I_m\otimes I_p\otimes B) \oslash I_n \\
   &= (A\otimes I_p\otimes I_n)\oslash I_n + (I_m\otimes C)\oslash I_n - (I_m\otimes I_p\otimes B) \oslash I_n \\
   &= A\otimes I_p + I_m\otimes(C\oslash I_n) - I_m\otimes I_p\otimes(B\oslash I_n) \\
   &= A\otimes I_p + I_m\otimes[(C\oslash I_n) - I_p\otimes (B\oslash I_n)] \\
   &= A\otimes I_p + I_m\otimes [(C-I_p\otimes B)\oslash I_n] \\
   &= A\otimes I_p + I_m\otimes (C\ominus B) \\
   &= A\oplus (C\ominus B).
 \end{align*}
 Finally, for all $A,B\in\mathbb{F}_{mn}$ and $C,D\in\mathbb{F}_n$,
 \begin{align*}
  (A+B)\ominus (C+D)
   &= (A+B-I_m\otimes C-I_m\otimes D)\oslash I_n \\
   &= (A-I_m\otimes C+ B-I_m\otimes D)\oslash I_n \\
   &= (A-I_m\otimes C)\oslash I_n + (B-I_m\otimes D)\oslash I_n \\
   &= A\ominus C + B\ominus D
 \end{align*}
 and for any scalar $k\in\mathbb{F}$,
 \begin{align*}
  (kA)\ominus (kC)
   &= (kA-I_m\otimes(kC))\oslash I_n \\
   &= [k(A-I_m\otimes C)]\oslash I_n \\
   &= k[(A-I_m\otimes C)\oslash I_n] \\
   &= k(A\ominus C). \qedhere
 \end{align*}
\end{proof}

Before studying Kronecker differences in more detail, we will need some additional definitions
and technical results. 
The presentations of these definitions and technicalities are left for Appendix \ref{sec:orthogonality} and Appendix \ref{sec:lemmata}.

