ref_dict.lem:proper:
\begin{lemma}
		\label{lem:proper}
		Under assumptions of Lemma~\ref{lem:mod}, for $t \in [T, T_1]$ there holds
		\begin{align}
			\big| \dd t a_1^+(t) - \frac{\nu}{\mu(t)^2}a_1^+(t)\big| &\leq \frac{c}{\mu(t)^2}|t|^{-\frac{N}{2(N-6)}}, \label{eq:proper-1p} \\
			\big| \dd t a_1^-(t) + \frac{\nu}{\mu(t)^2}a_1^-(t)\big| &\leq \frac{c}{\mu(t)^2}|t|^{-\frac{N}{2(N-6)}}, \label{eq:proper-1m} \\
			\big| \dd t a_2^+(t) - \frac{\nu}{\lambda(t)^2}a_2^+(t)\big| &\leq \frac{c}{\lambda(t)^2}|t|^{-\frac{N}{2(N-6)}}, \label{eq:proper-2p} \\
			\big| \dd t a_2^-(t) + \frac{\nu}{\lambda(t)^2}a_2^-(t)\big| &\leq \frac{c}{\lambda(t)^2}|t|^{-\frac{N}{2(N-6)}}, \label{eq:proper-2m}
		\end{align}
		with $c \to 0$ as $|T_0| \to +\infty$.
	\end{lemma}

ref_dict.lem:mod:
\begin{lemma}
		\label{lem:mod}
		Let $c > 0$ be an arbitrarily small constant. Let $T_0 < 0$ with $|T_0|$ large enough (depending on $c$)
		and $T < T_1 \leq T_0$. Suppose that for $T \leq t \leq T_1$ there holds
		\begin{align}
			\big|\zeta(t) + \frac{\pi}{2}\big| &\leq |t|^{-\frac{3}{N-6}}, \label{eq:bootstrap-zeta} \\
			|\mu(t) - 1| &\leq |t|^{-\frac{3}{N-6}}, \label{eq:bootstrap-mu} \\
			|\theta(t)| &\leq |t|^{-\frac{1}{N-6}}, \label{eq:bootstrap-theta} \\
			\big|\lambda(t) - \kappa|t|^{-\frac{2}{N-6}}\big| &\leq |t|^{-\frac{5}{2(N-6)}}, \label{eq:bootstrap-lambda} \\
			\|g\|_\cE &\leq |t|^{-\frac{N-1}{2(N-6)}}. \label{eq:bootstrap-g}
		\end{align}
		Then
		\begin{align}
			\label{eq:mod-zeta}
			|\zeta'(t)| &\leq c|t|^{-\frac{N-3}{N-6}}, \\
			\label{eq:mod-mu}
			|\mu'(t)| &\leq c|t|^{-\frac{N-3}{N-6}}, \\
			\label{eq:mod-l}
			\Big|\lambda'(t) - \frac{3C_2}{\|W\|_{L^2}^2} \lambda(t)^\frac{N-4}{2}\Big| &\leq c|t|^{-\frac{2N-7}{2(N-6)}}, \\
			\label{eq:mod-th}
			\Big|\theta'(t)+\frac{C_3}{\|W\|_{L^2}^2}\theta(t)\lambda(t)^\frac{N-6}{2}-\frac{K(t)}{\lambda(t)^2\|W\|_{L^2}^2}\Big| &\leq c|t|^{-\frac{N-5}{N-6}},
		\end{align}
		for $T \leq t \leq T_1$, where
		\begin{equation}
			\label{eq:kappa}
			\kappa := \Big(\frac{2C_1}{3(N-6)C_2}\Big)^{\frac{2}{N-6}},
		\end{equation}
		\begin{equation}
			\label{eq:K-def}
			K := -\big\la \eee^{i\theta}\Lambda W_\lambda, f(\eee^{i\zeta}W_{\mu} + \eee^{i\theta}W_{\lambda} + g) - f(\eee^{i\zeta}W_\mu + \eee^{i\theta}W_\lambda) - f'(\eee^{i\zeta}W_\mu + \eee^{i\theta}W_\lambda)g \big\ra.
		\end{equation}
	\end{lemma}

post_theorem_intro_text:
\begin{remark}
		More precisely, we will prove that
		\begin{equation*}
			\Big\|u(t) - \Big({-}iW + W_{\kappa|t|^{-\frac{2}{N-6}}}\Big)\Big\|_\mathcal{E} \leq C_0|t|^{-\frac{1}{2(N-6)}},
		\end{equation*}
		for some constant $C_0 > 0$.
	\end{remark}
	\begin{remark}
		We construct here \emph{pure} two-bubble, that is the solution approaches a superposition of two ground states, with no energy transformed into radiation.
		By the conservation of energy and the decoupling of the two bubbles, we necessarily have $E(u(t)) = 2E(W)$.
	\end{remark}
	\begin{remark}
		For energy-critical wave and NLS equations, similar objects were constructed by the first author in \cite{Jacek:wave} and \cite{Jacek:nls}. In the following work, we will consider dimension $N = 6$ and we expect an analogous result, with an exponential concentration rate. 
	\end{remark}
	\begin{remark}
	Solutions of similar kind for the energy-critical heat equation were constructed in \cite{dPMW, SWZ}.
	\end{remark}
		\begin{remark}
		Two-bubble solutions of a different kind were recently constructed in \cite{JK:wmaptwobub} for the energy-critical wave maps equation: the solution blows up in finite time, with the scales of both bubbles converging to zero simultaneously.
	\end{remark}

	\subsection{Outline of the proof}
	The overall structure is similar to the earlier work of the first author on the energy-critical NLS equations \cite{Jacek:nls}. The difference between Hartree equation here with NLS in \cite{Jacek:nls}  is the nonlocal interaction, which is more complex to analyze. The main tools are the modulation analysis, bootstrap argument and topological argument. 

	The paper is organized as follows. We study solutions of \eqref{har} close to a sum of two bubbles:
	\begin{equation}
		u(t) = \mathrm e^{i\zeta(t)}W_{\mu(t)} + \mathrm e^{i\theta(t)}W_{\lambda(t)} + g(t).
	\end{equation}
	One should think of $\zeta(t)$ as being close to $-\frac{\pi}{2}$, $\mu(t) \simeq 1$,
	$\theta(t) \sim 0$, $\lambda(t) \ll 1$ and $\|g(t)\|_\mathcal{E} \ll 1$. 

	In Section \ref{sec:variational}, we first recall some useful lemmas. We also state the spectral properties  of the linearized operator $Z_{\theta, \lambda}$ around $\mathrm e^{i\theta}W_\lambda$ and coercivity of the energy near a two-bubble. These are very important to estimate $g$, which is the infinite-dimensional part. We will use the energy conservation to deal with this.

	In Section \ref{sec:mod}, we estimate the modulation parameters. For this reason, we impose the orthogonality conditions which make the terms linear in $g$ in the modulation equations disappeared. There is essentially a unique choice of such orthogonality conditions. In Lemma~\ref{lem:mod} we establish bounds on the evolution of the modulation parameters under some bootstrap assumptions. The goal is to improve these bounds, thus closing the bootstrap. In order to improve the bound on $\|g\|_\mathcal{E}$ to close the bootstrap, we establish Lemma \ref{lem:proper} to control the unstable components.

	In Section \ref{sec:boot}, we establish the bootstrap estimates and prove the main result Theorem \ref{thm:deux-bulles}. First, we use implicit function theorem to obtain the modulation decomposition. Next, combining with virial correction, which is used to improve the bound \eqref{eq:bootstrap-theta} on $\theta(t)$, we can close the bootstrap of modulation parameters. Adding the virial correction allows us to gain a small constant on the right hand side of \eqref{eq:mod-th}, which is decisive for closing the bootstrap. The linear instabilities of the flow can be handled by using a classical topological argument based on the Brouwer fixed point theorem. Finally, we prove Theorem \ref{thm:deux-bulles}.

	\subsection{Acknowledgments}
