The authors give an ``\subsection{Outline of the proof}'' to prove the main theorem. They study solutions close to a sum of two bubbles via the modulation decomposition
\[
 u(t)=e^{i\zeta(t)}W_{\mu(t)}+e^{i\theta(t)}W_{\lambda(t)}+g(t),
\]
with ``$\zeta(t)$ close to $-\frac{\pi}{2}$, $\mu(t)\simeq 1$, $\theta(t)\sim 0$, $\lambda(t)\ll 1$ and $\|g(t)\|_{\mathcal E}\ll 1$.'' The main tools are stated to be ``modulation analysis, bootstrap argument and topological argument.''

Key steps (as described):
\begin{itemize}
\item Next they recall variational and spectral ingredients; they state ``the spectral properties of the linearized operator $Z_{\theta,\lambda}$'' and ``coercivity of the energy near a two-bubble,'' which are ``very important to estimate $g$''; they ``use the energy conservation to deal with this.''
\item Then they estimate modulation parameters by imposing orthogonality conditions so that ``the terms linear in $g$ in the modulation equations disappeared'' (with ``essentially a unique choice"). Under bootstrap assumptions, they use the following lemma.

\begin{lemma}
		\label{lem:mod}
		Let $c > 0$ be an arbitrarily small constant. Let $T_0 < 0$ with $|T_0|$ large enough (depending on $c$)
		and $T < T_1 \leq T_0$. Suppose that for $T \leq t \leq T_1$ there holds
		\begin{align}
			\big|\zeta(t) + \frac{\pi}{2}\big| &\leq |t|^{-\frac{3}{N-6}}, \label{eq:bootstrap-zeta} \\
			|\mu(t) - 1| &\leq |t|^{-\frac{3}{N-6}}, \label{eq:bootstrap-mu} \\
			|\theta(t)| &\leq |t|^{-\frac{1}{N-6}}, \label{eq:bootstrap-theta} \\
			\big|\lambda(t) - \kappa|t|^{-\frac{2}{N-6}}\big| &\leq |t|^{-\frac{5}{2(N-6)}}, \label{eq:bootstrap-lambda} \\
			\|g\|_\cE &\leq |t|^{-\frac{N-1}{2(N-6)}}. \label{eq:bootstrap-g}
		\end{align}
		Then
		\begin{align}
			\label{eq:mod-zeta}
			|\zeta'(t)| &\leq c|t|^{-\frac{N-3}{N-6}}, \\
			\label{eq:mod-mu}
			|\mu'(t)| &\leq c|t|^{-\frac{N-3}{N-6}}, \\
			\label{eq:mod-l}
			\Big|\lambda'(t) - \frac{3C_2}{\|W\|_{L^2}^2} \lambda(t)^\frac{N-4}{2}\Big| &\leq c|t|^{-\frac{2N-7}{2(N-6)}}, \\
			\label{eq:mod-th}
			\Big|\theta'(t)+\frac{C_3}{\|W\|_{L^2}^2}\theta(t)\lambda(t)^\frac{N-6}{2}-\frac{K(t)}{\lambda(t)^2\|W\|_{L^2}^2}\Big| &\leq c|t|^{-\frac{N-5}{N-6}},
		\end{align}
		for $T \leq t \leq T_1$, where
		\begin{equation}
			\label{eq:kappa}
			\kappa := \Big(\frac{2C_1}{3(N-6)C_2}\Big)^{\frac{2}{N-6}},
		\end{equation}
		\begin{equation}
			\label{eq:K-def}
			K := -\big\la \eee^{i\theta}\Lambda W_\lambda, f(\eee^{i\zeta}W_{\mu} + \eee^{i\theta}W_{\lambda} + g) - f(\eee^{i\zeta}W_\mu + \eee^{i\theta}W_\lambda) - f'(\eee^{i\zeta}W_\mu + \eee^{i\theta}W_\lambda)g \big\ra.
		\end{equation}
	\end{lemma}

Their goal is to ``improve these bounds, thus closing the bootstrap.'' To improve the bound on $\|g\|_{\mathcal E}$ they use the following lemma to ``control the unstable components.''

\begin{lemma}
		\label{lem:proper}
		Under assumptions of Lemma~\ref{lem:mod}, for $t \in [T, T_1]$ there holds
		\begin{align}
			\big| \dd t a_1^+(t) - \frac{\nu}{\mu(t)^2}a_1^+(t)\big| &\leq \frac{c}{\mu(t)^2}|t|^{-\frac{N}{2(N-6)}}, \label{eq:proper-1p} \\
			\big| \dd t a_1^-(t) + \frac{\nu}{\mu(t)^2}a_1^-(t)\big| &\leq \frac{c}{\mu(t)^2}|t|^{-\frac{N}{2(N-6)}}, \label{eq:proper-1m} \\
			\big| \dd t a_2^+(t) - \frac{\nu}{\lambda(t)^2}a_2^+(t)\big| &\leq \frac{c}{\lambda(t)^2}|t|^{-\frac{N}{2(N-6)}}, \label{eq:proper-2p} \\
			\big| \dd t a_2^-(t) + \frac{\nu}{\lambda(t)^2}a_2^-(t)\big| &\leq \frac{c}{\lambda(t)^2}|t|^{-\frac{N}{2(N-6)}}, \label{eq:proper-2m}
		\end{align}
		with $c \to 0$ as $|T_0| \to +\infty$.
	\end{lemma}

\item Finally, in establishing the main theorem: first they use the implicit function theorem to obtain the modulation decomposition; then, ``combining with virial correction'' (to improve the bound
\begin{align}
			\big|\zeta(t) + \frac{\pi}{2}\big| &\leq |t|^{-\frac{3}{N-6}}, \label{eq:bootstrap-zeta} \\
			|\mu(t) - 1| &\leq |t|^{-\frac{3}{N-6}}, \label{eq:bootstrap-mu} \\
			|\theta(t)| &\leq |t|^{-\frac{1}{N-6}}, \label{eq:bootstrap-theta} \\
			\big|\lambda(t) - \kappa|t|^{-\frac{2}{N-6}}\big| &\leq |t|^{-\frac{5}{2(N-6)}}, \label{eq:bootstrap-lambda} \\
			\|g\|_\cE &\leq |t|^{-\frac{N-1}{2(N-6)}}. \label{eq:bootstrap-g}
		\end{align}
on $\theta(t)$) they close the bootstrap for modulation parameters. They explain that the virial correction ``allows us to gain a small constant on the right hand side of
\begin{align}
			\label{eq:mod-zeta}
			|\zeta'(t)| &\leq c|t|^{-\frac{N-3}{N-6}}, \\
			\label{eq:mod-mu}
			|\mu'(t)| &\leq c|t|^{-\frac{N-3}{N-6}}, \\
			\label{eq:mod-l}
			\Big|\lambda'(t) - \frac{3C_2}{\|W\|_{L^2}^2} \lambda(t)^\frac{N-4}{2}\Big| &\leq c|t|^{-\frac{2N-7}{2(N-6)}}, \\
			\label{eq:mod-th}
			\Big|\theta'(t)+\frac{C_3}{\|W\|_{L^2}^2}\theta(t)\lambda(t)^\frac{N-6}{2}-\frac{K(t)}{\lambda(t)^2\|W\|_{L^2}^2}\Big| &\leq c|t|^{-\frac{N-5}{N-6}},
		\end{align}
which is decisive for closing the bootstrap.'' Linear instabilities are handled by ``a classical topological argument based on the Brouwer fixed point theorem.'' This completes the proof of the main theorem.
\end{itemize}

