ref_dict.theorem:unigen:
\begin{theorem} \label{theorem:unigen}
Let $\cloA$, $\cloB$ be clones, $n \geq 1$, and let $\cloA_{const} = \Clo(\cloA \cup \{a\}_{a\in A})$ be the clone generated by $\cloA$ and all constant operations over its set. Let $\clodC$ a clonoid from $\cloA_{const}$
to $\cloB$. Then the following are equivalent:
\begin{enumerate}
\item\label{ite:th_unigen1} $\clodC^{(n+1)}$ is $(n,\cloA,\cloB)$-UG
\item\label{ite:th_unigen2} $\clodC^{(k)}$ is $(n,\cloA,\cloB)$-UG for some $k>n$
\item\label{ite:th_unigen3} $\clodC$ is $(n,\cloA,\cloB)$-UG
\item\label{ite:th_unigen4} $\forall k,l \in \N$, every partial operation $I \colon \clodC^{(k)} \to \clodC^{(l)}$ 
that is $(\cloA,\cloB)$-UR is $(n,\cloA,\cloB)$-UR.
\end{enumerate}
\end{theorem}

ref_dict.conjecture:main:
\begin{conjecture} \label{conjecture:main}
Let $\algA$ and $\algB$ be finite modules. Then, there are only finitely many clonoids from $\algA$ to $\algB$, if and only if $\algA$ and $\algB$ are of coprime order.
\end{conjecture}

ref_dict.theorem:clonoidlattice:
\begin{theorem} \label{theorem:clonoidlattice}
The lattice of clonoids from $\F^k$ to $\algB$ is isomorphic to $\prod_{i=0}^k \Sub(\algM_{i,k}(\F,\algB))$.

Moreover, for $j\leq k$, the sublattice $\prod_{i=0}^j \Sub(\algM_{i,k}(\F,\algB))$ corresponds to the clonoids consisting of functions that are generated by their $j$-ary minors.
\end{theorem}

ref_dict.eqn;afford:
\begin{pr}{Proposition \ref{prop;LWP}}
By virtue of Lemmas~\ref{lem;fixed-point} and~\ref{lem;continuous-depend},
we have established the existence of a unique mild solution to~\eqref{eqn;KS} defined on a maximal time interval $[0,T)$ with~$T\le\infty$. As for the regularity of the solutions, we use the standard iteration argument with respect to the derivative. Define $|\N|^\al f(x):=\F^{-1}[ |\xi|^\al \F f(\xi)\,](x)$  for $x\in\R^2$ and $\al>0$, where $\F$ denotes the Fourier transform. Let $\tau\in (0,T)$ and $t\in (0,\tau)$. Recalling that, for $4/3<p<2$,
\begin{equation*}
U_{p,0}(\tau) := \sup_{0< s<\tau}s^{1-\frac1p}\|u(s)\|_{p}<+\infty, \quad V_{q,0}(\tau) := \sup_{0< s<\tau}s^{\frac12-\frac1q}\|\nabla v(s)\|_{q}<+\infty,
\end{equation*}
by Lemma~\ref{lem;fixed-point}, we may argue as in the proof of~\eqref{eqn;L-4/3} to obtain
\begin{align*}
&t^{1-\frac1p+\frac{\al}{2}} \| |\N|^{\al} u(t) \|_{p}
\\
\le\,& t^{1-\frac1p+\frac{\al}{2}} \| |\N|^\al e^{t\Del}u_0\|_{p} + C U_{p,0}(\tau) V_{q,0}(\tau) t^{1-\frac1p+\frac{\al}{2}}  \int_0^t  (t-s)^{-1+\frac1{p}-\frac{1+\al}2} s^{-1+\frac{1}p} s^{-\frac12+\frac1q}\,\d s
\\
\le\,&C\|u_0\|_1 + C  U_{p,0}(\tau) V_{q,0}(\tau) \mathsf{B}\left(\frac1p-\frac{1+\al}2,\frac12\right),
\end{align*}
where $4/3<p<2$ and
\begin{align*}
\al <\frac2p-1<\frac12,
\end{align*}
which implies that
\begin{align*}
U_{p.\al}(\tau):=\sup_{0< t<\tau} t^{1-\frac1p+\frac{\al}{2}} \| |\N|^{\al} u(t)\|_{p} <+\infty,
\quad
\al<\frac2p-1.
\end{align*}
This property yields additional regularity estimates for $v$. Indeed, for $\bt\ge \al$, 
\begin{align*}
\| |\N|^{1+\beta} v(t) \|_{q}
\le\,&C t^{-\frac12+\frac1q-\frac\bt2} \| \nabla v_0\|_{2} + C U_{p,\al}(\tau) \int_0^t (t-s)^{-\left(\frac1p-\frac1q\right)-\frac{1+\bt-\al}{2} } s^{-1+\frac1p-\frac\al2}\,\d s 
\\
=\,&C  t^{-\frac12+\frac1q-\frac\bt2} \| \nabla v_0\|_{2} 
+C U_{p,\al}(\tau)  t^{-\frac12+\frac1q-\frac\bt2} \mathsf{B}\left(\frac12-\frac1p+\frac1q-\frac{\bt-\al}{2}, \frac1p-\frac{\al}{2}\right),
\end{align*}
provided that
\begin{align*}
\al\le \bt<\al+3-\frac4p<2-\frac2p<1,
\end{align*}
from which it follows that 
\begin{align*}
V_{q,\bt}(\tau) := \sup_{0< t<\tau} t^{\frac12-\frac1q+\frac\bt2} \| |\N|^{1+\bt} v(t) \|_{q}<+\infty,
\quad  \bt<\al+3-\frac4p\in (\al,1).
\end{align*}
The previous analysis leads us to a higher regularity estimate for $u$. Indeed, let $\th\ge\al$. Since $\al\le\bt\le\gm$,
\begin{align*}
& \| |\N|^{\th}u(t)\|_{p} \\
\le\,&C t^{-\left(1-\frac1p\right)-\frac\th2}\|u_0\|_1
\\
&+C\int_0^t(t-s)^{-\left(1-\frac1p\right)-\frac{1+\th-\al}{2}} \left(\||\N|^{\al} u(s)\|_{p}\|\nabla v(s)\|_q+\|u(s)\|_{p}\| |\N|^{1+\al} v(s)\|_{q}\right)\,\d s
\\
\le\,&Ct^{-\left(1-\frac1p\right)-\frac\th2}\|u_0\|_1
\\
&+ C \big(U_{p,\alpha}(\tau) V_{q,0}(\tau) + U_{p,0}(\tau) V_{q,\al}(\tau)\big) 
\int_0^t(t-s)^{-\left(1-\frac1p\right)-\frac{1+\th-\al}{2}} s^{-\frac32+\frac1p+\frac1q-\frac{\al}{2}}\,\d s
\\
=\,&Ct^{-\left(1-\frac1p\right)-\frac\th2}\|u_0\|_1
\\
& + C \big(U_{p,\al}(\tau) V_{q,0}(\tau) + U_{p,\al}(\tau) V_{q,0}(\tau)\big) t^{-\left(1-\frac1p\right)-\frac\th2} \mathsf{B}\left(\frac1p-\frac{1+\th-\al}{2},\frac12-\frac\al2\right),
\end{align*}
where
\begin{align*}
\al \le \th<\al+\frac2p-1<1,\quad
\al<\frac2p-1.
\end{align*}
Hence, 
\begin{align*}
U_{p,\th}(\tau) = \sup_{0< t< \tau}t^{1-\frac1p+\frac{\th}{2}}\||\N|^\th u(t)\|_{p}<+\infty,
\quad
\al \le \th<\al+\frac2p-1<1,\quad
\al<\frac2p-1.
\end{align*}
Iterating further the above arguments, we obtain that the solution possesses higher regularity. In fact, using the uniqueness result established in Lemma~\ref{lem;continuous-depend}, we may solve the problem~\eqref{eqn;KS} with the initial data $(u(t_0),v(t_0))$ for some $t_0\in (0,T)$. We thus eventually show that for $s>0$, $u(t)\in L^1(\R^2)\cap W^{s,p}(\R^2)$,
$v(t)\in  \dot{H}^{1}(\R^2)\cap W^{s,q}(\R^2)$
for $t_0<t<T$, 
and satisfies the system~\eqref{eqn;KS} in a  classical sense on $(0,T)\times\R^2$.
Also, classical arguments based on the proof of Lemma~\ref{lem;fixed-point} lead to the blowup criterion~\eqref{eqn;bucrit}.

Let  $(u_0,v_0)$ be nonnegative initial conditions with $u_0,v_0\not\equiv0$ and
$\{u_{0,k}\}_{k\in\Nt }$ and
$\{v_{0,k}\}_{k\in\Nt }$ be sequences
of nonnegative functions in $C_0^{\infty}(\R^2)$ converging to $u_0$ in $L^{1}(\R^2)$ and $v_0$ in $\dot{H}^{1}(\R^2)$  as $k\to\infty$, respectively. Then, for each $k\in\Nt$, we can construct the unique, smooth and integrable solution
to~\eqref{eqn;KS} corresponding to the initial data $(u_{0,k},v_{0,k})$.
By the parabolic regularity theory,
the solutions $(u_k,v_k)$ belong to $C^{\infty}( [0,T)\times \R^2)$
and are positive on $(0,T)\times\R^2$. In addition, by the continuous dependence on the initial data established in Lemma~\ref{lem;continuous-depend}, we have the convergences $u_k\to u$ in $C\big([0,T); L^1(\R^2)\big)$ and $v_k\to v$ in $C\big([0,T); \dot{H}^{1}(\R^2)\big)$ as $ k\to \infty$,
where $(u,v)$ is the solution to~\eqref{eqn;KS} with initial data $(u_0,v_0)$. Hence, one can find subsequences of the approximated solutions
which converge to $(u,v)$ almost everywhere in $(0,T)\times\R^2$, which implies that $u$ and $v$ are positive on $(0,T)\times\R^2$.
Moreover the mass conservation law also holds by integrating $u$ over $\R^2$.
\end{pr}

\vspace{5mm}
\section{Global existence of solutions with critical mass}\label{sect;global}

In this section, we prove the global existence of solutions to \eqref{eqn;KS}
with critical mass, as stated in Theorem~\ref{thm;global}.
To this end, we divide the proof into several steps.

In Subsection~\ref{sect;modified-Lyapunov}, we introduce a suitably reconstructed
Lyapunov functional and derive regularity estimates for the associated
dissipative terms.
In Subsection~\ref{sect;exterior}, we establish various regularity estimates
in exterior domains by using the estimates obtained in
Subsection~\ref{sect;modified-Lyapunov}.
Thanks to the results in the previous subsections, we then derive interior
regularity estimates in Subsection~\ref{sect;interior}.
Finally, in Subsection~\ref{sect;main}, we complete the proof of
Theorem~\ref{thm;global} by combining the exterior and interior estimates.

Throughout this section, we denote by $(u,v)$ the solution to~\eqref{eqn;KS}
with maximal existence time $T\le\infty$.
In the following, we derive a priori estimates on $[t_0,\tau]\cap(0,T)$ for arbitrary $t_0,\tau$ with $t_0<\tau$, which will allow us to conclude global existence by a contradiction argument.
Moreover, $C$ denotes a generic positive constant depending only on $\lambda$
and the initial data~$(u_0,v_0)$, which may vary from line to line.
The dependence of $C$ on additional parameters will be indicated explicitly.

\subsection{Refined Lyapunov  functional}\label{sect;modified-Lyapunov}

We here introduce a suitably reconstructed Lyapunov functional which is non-increasing along the evolution of solutions, and derive regularity estimates associated with the corresponding dissipation mechanism. These estimates further yield refined regularity properties for solutions to \eqref{eqn;KS}.

The existence of a Lyapunov functional is known to play a fundamental role in the analysis of the long-time behavior of solutions, including global existence and finite-time blowup phenomena. In the whole space setting, however, the use of Lyapunov-based methods in~\eqref{eqn;KS} faces intrinsic difficulties due to 
 the necessity of controlling the behavior as $|x|\to\infty$. This issue becomes particularly delicate at the critical mass.

First of all, it is worth mentioning that the system \eqref{eqn;KS} has a usual Lyapunov functional~$\L(t)$ as follows:
\begin{align*}
\frac{\d}{\d t}\L(t)+ \D(t) =0,
\eqntag
\label{eqn;Lyapunov}
\end{align*}
where
\begin{align*}
\L(t):=\int_{\R^2}u\ln u\dx-\int_{\R^2}uv\dx+\frac12\|\nabla v\|_2^2+\frac\lambda2\|v\|_2^2
\end{align*}
and the dissipative term $\D(t)$ is given by
\begin{align*}
\D(t):=\int_{\R^2} u \left|\nabla(\ln u -v)\right|^2\dx+\|\partial_t v\|_2^2.
\end{align*}
The upper bound for $\L(t)$ follows from the monotonicity \eqref{eqn;Lyapunov} and 
the lower bound for that can be obtained by the optimal constraint of the initial mass $\|u_0\|_1$ deriving from the Trudinger--Moser type inequality and its best possible constant, see \cite{Na-Se-Yo} and also \cite{CaCo08,Mi13,NaOg11} for instance.
On the other hand,
in order to ensure the well-definedness of a usual entropy $\int_{\R^2}u\ln u \dx$ on the whole space,
at least the logarithmic moment assumption for the initial data $u_0\ln(1+|x|^2)\in L^1(\R^2)$ is required to control the behavior of solutions as $|x|\to\infty$, that is,
\begin{align*}
-\int_{\R^2}u(\ln u)_-\dx \le\,C\int_{\R^2}u\ln(1+|x|^2)\dx,
\end{align*}
where $(\ln u)_-:=\min\{\ln u,0\}$, according to \cite[Lemma 2.4]{CaCo08}.
Later, to get rid of any moment assumptions,
the modified entropy is adapted by Nagai \cite{Na11};
\begin{align*}
\int_{\R^2}(1+u)\ln(1+u)\dx,
\end{align*}
as well as the following identity for the modified Lyapunov functional $\L_m(t)$ is introduced:
\begin{align*}
\frac{\d}{\d t} \L_m(t) + \D_m(t)=\frac14\|\nabla v(t)\|_2^2,
\eqntag
\label{eqn;usualmodifiedfunctiona}
\end{align*}
where
\begin{align*}
\L_m(t):=\int_{\R^2}(1+u)\ln(1+u)\dx-\int_{\R^2}uv\dx+\frac12\|\nabla v\|_2^2+\frac\lambda2\|v\|_2^2
\end{align*}
and
\begin{align*}
\D_m(t):=\int_{\R^2}u\left|\nabla(\ln(1+u)-v)\right|^2\dx+\int_{\R^2}\left|\nabla\left(\ln(1+u)-\frac12v\right)\right|^2\dx+\|\partial_tv\|_2^2.
\end{align*}
The functional $\L_m(t)$ is no longer the Lyapunov functional, however, it is still useful for proving 
the global existence of the solution to \eqref{eqn;KS} with sub-critical mass. Indeed, it follows
from the lower bound for $\L_m(t)$ that
for any $\al\in[0,1)$
\begin{align*}
\al\int_{\R^2}(1+u)\ln(1+u)\dx+\frac12\left[1-\frac{\|u_0\|_1}{8\pi(1-\al)}\right]&\|\nabla v\|_2^2
+\int_0^t \D_m(s)\,\d s
\\
\le\,&\L_m(0)+C(\tau,\alpha)+\frac14\int_0^t\|\nabla v\|_2^2\,\d s
\eqntag
\label{eqn;afford}
\end{align*}
for $t\in[0,\tau]\cap(0,T)$ with any $\tau>0$ and some $C(\tau,\alpha)>0$ (cf.~\cite{CaCo08,Mi13}). Hence, if $\|u_0\|<8\pi$, then all terms on the left hand side of \eqref{eqn;afford} are positive by choosing $\al>0$ sufficiently small which depends on $\|u_0\|_1$, and Gronwall's inequality implies that
$\nabla v \in L^2((0,T)\times \R^2)$, 
so that we also obtain the bound for the modified entropy $\int_{\R^2}(1+u)\ln (1+u)\dx$. 
Nevertheless, for the critical mass $\|u_0\|_1=8\pi$, this necessarily leads to $\alpha=0$, as a result, 
\begin{align*}
\int_0^t \D_m(s)\,\d s\le\,&\L_m(0)+C(\tau)+\frac14\int_0^t\|\nabla v\|_2^2\,\d s,
\eqntag
\label{eqn;lack-lyapunov}
\end{align*}
which is useless and fails to obtain even the estimates for $\D_m(t)$ due to the lack of the regularity of solutions.
Therefore, we introduce a reconstructed Lyapunov functional $\F_m(t)$ so as to show regularity estimates corresponding to the dissipative terms. Let $\F_m(t)$ be the functional for solutions to \eqref{eqn;KS} defined as
\begin{align*}
\F_m(t):=\L_m(t)
+\int_{\R^2}\ln(1+u)\,\mathrm{d}x-\int_{\R^2}v\,\d x.
\eqntag
\label{eqn;modifiedLyapunov}
\end{align*}
Then, the following functional differential inequality holds true:
\begin{prop}\label{prop;energy-est}
Let $(u,v)$ be the solution to \eqref{eqn;KS}. Then, the functional $\F_m(t)$ defined in~\eqref{eqn;modifiedLyapunov} satisfies the following identity:
	\begin{align*}
	\frac{\d}{\d t}\F_m(t) +\int_{\R^2}u\left|\nabla\left(\ln(1+u)-v\right)\right|^2\,\mathrm{d}x+\frac12\|\partial_tv\|_2^2
	\le\,&
	\lambda\int_{\R^2}v\,\d x.
	\end{align*}
	Therefore, if $\lambda=0$ then
	\begin{align*}
	\frac{\d}{\d t}\F_m(t) +\int_{\R^2}u\left|\nabla\left(\ln(1+u)-v\right)\right|^2\,\mathrm{d}x+\frac12\|\partial_tv\|_2^2 \le\,0.
	\end{align*}
	If $\lambda>0$ then 
	\begin{align*}
	\frac{\d}{\d t}\F_m(t) +\int_{\R^2}u\left|\nabla\left(\ln(1+u)-v\right)\right|^2\,\mathrm{d}x+\frac12\|\partial_tv\|_2^2 \le\,\|v_0\|_1+\|u_0\|_1.
	\end{align*}
\end{prop}
\vspace{5mm}
It is worth emphasizing that $\F_m(t)$ is non-increasing in time when $\lambda=0$ as well as
unlike the identity \eqref{eqn;usualmodifiedfunctiona} based on the usual modified functional $\mathcal{L}_m(t)$, the error term appearing on the right-hand side of Proposition~\ref{prop;energy-est} can be easily controlled by initial data.
This allows us to show the regularity estimates for the dissipative term associated with $\F_m(t)$, see Proposition~\ref{prop;bound-energy} below.
\begin{lem}\label{lem;ModifiedLF}
	Suppose assumptions as in Theorem \ref{thm;global}. Then,
\begin{align*}
\frac{\d}{\d t}\F_m(t)+ \widetilde{\D}(t)=-\int_{\R^2}\partial_t v \frac{u}{1+u}\,\d x-\int_{\R^2}\frac{u}{1+u}\,\mathrm{d}x+\lambda\int_{\R^2}\frac{v}{1+u}\,\d x,
\end{align*}
where
$\F_m(t)$ is the modified functional defined in \eqref{eqn;modifiedLyapunov} and the dissipative term $\widetilde{\D}(t)$ is given by
\begin{align*}
\widetilde{\D}(t):=\int_{\R^2}u\left|\nabla \left(\ln(1+u)-v\right)\right|^2\,\d x+\|\partial_t v\|_2^2.
\end{align*}
\end{lem}

\begin{pr}{Lemma \ref{lem;ModifiedLF}}
The following computations are already well-known:
\begin{align*}
\frac{\d}{\d t} \int_{\R^2}(1+u)\ln (1+u)\,\d x=\,&
-\int_{\R^2}(1+u)|\nabla\ln(1+u)|^2\,\d x
+\int_{\R^2}u\nabla\ln(1+u)\cdot\nabla v\,\d x
\end{align*}
as well as
\begin{align*}
-\frac{\d}{\d t}\int_{\R^2}uv\,\d x=\,&\int_{\R^2}(1+u)\nabla\ln(1+u)\cdot\nabla v\,\d x-\int_{\R^2}u|\nabla v|^2\,\d x
\\
&-\|\partial_tv\|_2^2-\frac12\frac{\d}{\d t}\|\nabla v\|_2^2-\frac\lambda2\frac{\d}{\d t}\|v\|_2^2,
\end{align*}
so that
\begin{align*}
&\frac{\d}{\d t}\left[\int_{\R^2}(1+u)\ln(1+u)\,\d x-\int_{\R^2}uv\,\d x+\frac12\left(\|\nabla v\|_2^2+\lambda\|v\|_2^2\right)\right]
\\
&+\int_{\R^2}u\left|\nabla\left(\ln(1+u)-v\right)\right|^2\,\mathrm{d}x+\|\partial_tv\|_2^2
\\
=\,&-\|\nabla\ln(1+u)\|_2^2+\int_{\R^2}\nabla\ln(1+u)\cdot\nabla v\,\d x.
\end{align*}
Next,
\begin{align*}
\frac{\d}{\d t}\int_{\R^2}\ln(1+u)\,\d x=\,&\int_{\R^2}\frac{1}{1+u} \left[\Delta u -\nabla\cdot( u\nabla v)\right]\,\mathrm{d}x
\\
=\,&-\int_{\R^2}\nabla\left(\frac{1}{1+u}\right)\cdot \nabla u\,\d x+\int_{\R^2}u\nabla\left(\frac{1}{1+u}\right)\cdot \nabla v\,\d x
\\
=\,&\int_{\R^2}|\nabla \ln(1+u)|^2\,\d x-\int_{\R^2}\frac{u}{1+u}\nabla\ln(1+u)\cdot\nabla v\,\d x
\\
=\,&\int_{\R^2}|\nabla \ln(1+u)|^2\,\d x-\int_{\R^2}\nabla\ln(1+u)\cdot\nabla v\,\d x
\\
&+\int_{\R^2}\frac{1}{1+u}\nabla\ln(1+u)\cdot\nabla v \,\d x.
\end{align*}
Hence, combining the above computations implies that
\begin{align*}
&\frac{\d}{\d t}\left[\int_{\R^2}(1+u)\ln(1+u)\,\d x-\int_{\R^2}uv\,\d x+\frac12\left(\|\nabla v\|_2^2+\lambda\|v\|_2^2\right)+\int_{\R^2}\ln(1+u)\,\d x\right]
\\
&+\int_{\R^2}u\left|\nabla\left(\ln(1+u)-v\right)\right|^2\,\mathrm{d}x+\|\partial_tv\|_2^2
\\
=\,&\int_{\R^2}\frac{1}{(1+u)^2}\nabla u\cdot\nabla v \,\d x.
\end{align*}
Since
\begin{align*}
\int_{\R^2}\frac{1}{(1+u)^2}\nabla u\cdot\nabla v \,\d x=\,&-\int_{\R^2}\nabla\left(\frac{1}{1+u}\right)\cdot \nabla v\,\d x
\\
=\,&\int_{\R^2}\frac{1}{1+u}\Delta v\,\d x
\\
=\,&\int_{\R^2}\frac{\partial_t v}{1+u}\,\d x-\int_{\R^2}\frac{u}{1+u}\,\d x+\lambda\int_{\R^2}\frac{v}{1+u}\,\d x
\\
=\,&\frac{\d}{\d t}\int_{\R^2}v\,\d x-\int_{\R^2}\partial_t v \frac{u}{1+u}\,\d x-\int_{\R^2}\frac{u}{1+u}\,\d x+\lambda\int_{\R^2}\frac{v}{1+u}\,\d x,
\end{align*}
we end up with
\begin{align*}
&\frac{\d}{\d t}\F_m(t)+\int_{\R^2}u\left|\nabla\left(\ln(1+u)-v\right)\right|^2\,\mathrm{d}x+\|\partial_tv\|_2^2
\\
=\,&-\int_{\R^2}\partial_t v \frac{u}{1+u}\,\d x-\int_{\R^2}\frac{u}{1+u}\,\d x+\lambda\int_{\R^2}\frac{v}{1+u}\,\d x,
\end{align*}
as desired.
\end{pr}

ref_dict.thm;global:
\begin{thm}\label{thm;global}
For $(u_0,v_0)\in L_+^1(\R^2) \times L^1_+(\R^2)\cap \dot{H}^1(\R^2)$,
let $(u,v)$ be the solution to \eqref{eqn;KS} on $(0,T)\times\R^2$.
Suppose that $\|u_0\|_1=8\pi$.
Then, the solution to \eqref{eqn;KS} exists globally in time.
\end{thm}

post_theorem_intro_text:
\noindent A key step to the extension is the construction of harmonic metrics at all points of $\mathcal{M}_{2,3}$. We constructed the metrics in the way that the equations for them are similar to the ones considered at fixed point (Toda type equations). In fact, the equations are some smooth perturbations of the ones at fixed point. Elliptic estimates and other techniques in PDE's allow us to show

\begin{theorem}
  The extended norm $\mu$ is smooth on $\mathcal{M}_{2,3}$.
  \label{Smoothness Metric intro}
\end{theorem}

\noindent The extended norm, in particular, defines a moment map for the $U(1)$-action on $\Ms$ and a small part of $\Mb$. In spite of the achieved extension, the definition on $\Mb$ is still somewhat vague. We are therefore unable to fully answer the conjecture posed in \cite{FN} about the precise description on the monotonicities of $\mu$. We leave it as continuing direction toward other generalizations in the future.

theorem.content:
Assume that there exist $\delta > 0,\:  0 < \rho < \min\{1, h^{-1}\},\: c_0 > 5 - \frac{h\rho}{3}$ and a sequence $q_j \nearrow +\infty$ such that
\begin{eqnarray} \label{eq:1.8}
\sharp \big\{ \gamma \in \Pi_{+}:\: q_j - \rho < \tau(\gamma) \leq q_j, \nonumber \\
\:|\tau(\gamma) - \tau(\gamma')| \geq e^{-\delta \max\{\tau(\gamma), \tau(\gamma') \}}, \: \forall \gamma' \in \Pi \setminus \{\gamma\}\big\} \geq \frac{c_0 \rho e^{\frac{hq_j}{3}}}{8q_j}.
\end{eqnarray}
Then the condition $(LB)$ is satisfied for $F_D.$

